extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Il nodo Player deve essere presente"):
		return
	player.position = Vector2(200, 200)
	var initial_children := main.get_child_count()
	await tap_action("shoot")
	await wait_physics_frames(5)
	var new_children := main.get_child_count()
	check("bullet_created", new_children > initial_children, "Premendo il tasto di sparo deve essere creato un proiettile nella scena principale")

	var bullets := find_all_by_class(main, "Area2D")
	var spawned_bullet: Area2D = null
	for b in bullets:
		if b.name.begins_with("Bullet"):
			spawned_bullet = b as Area2D
			break
	if check("bullet_found", spawned_bullet != null, "È stato creato un nodo chiamato Bullet nella scena"):
		var pos1 := spawned_bullet.global_position
		await wait_physics_frames(10)
		var pos2 := spawned_bullet.global_position
		check("bullet_moves", pos1.distance_to(pos2) > 10.0, "Il proiettile si deve muovere nel tempo (distanza percorsa: %.1f px)" % pos1.distance_to(pos2))

