extends CharacterBody2D

@export var speed: float = 120.0
@export var acceleration: float = 800.0
@export var friction: float = 600.0
@export var target_position: Vector2 = Vector2.ZERO


func _physics_process(delta: float) -> void:
	var distance: float = global_position.distance_to(target_position)
	if distance > 4.0:
		var direction: Vector2 = global_position.direction_to(target_position)
		if direction != Vector2.ZERO:
			rotation = direction.angle()
			var target_velocity: Vector2 = direction * speed
			velocity = velocity.move_toward(target_velocity, acceleration * delta)
	else:
		velocity = velocity.move_toward(Vector2.ZERO, friction * delta)

	move_and_slide()

extends Node2D

@onready var ground: TileMapLayer = $Ground
@onready var walls: TileMapLayer = $Walls
@onready var decoration: TileMapLayer = $Decoration
@onready var camera: Camera2D = $Player/Camera2D


func _ready() -> void:
	for x in range(50):
		for y in range(35):
			ground.set_cell(Vector2i(x, y), 0, Vector2i(2, 0))

	for x in range(50):
		for y in range(35):
			if (x == 0 or x == 49 or y == 0 or y == 34) and not (x == 25 and y == 34):
				walls.set_cell(Vector2i(x, y), 0, Vector2i(3, 0))
			else:
				walls.set_cell(Vector2i(x, y), -1)

	decoration.set_cell(Vector2i(3, 3), 0, Vector2i(2, 1))

	setup_camera_limits()


func setup_camera_limits() -> void:
	var used_rect: Rect2i = ground.get_used_rect()
	var tile_size: Vector2i = ground.tile_set.tile_size

	camera.limit_left = used_rect.position.x * tile_size.x
	camera.limit_top = used_rect.position.y * tile_size.y
	camera.limit_right = used_rect.end.x * tile_size.x
	camera.limit_bottom = used_rect.end.y * tile_size.y
	camera.reset_smoothing()

extends Area2D

@export var zone_message: String = "Premi Shift per scattare!"
@export var message_label: Label


func _ready() -> void:
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)


func _on_body_entered(body: Node2D) -> void:
	if body.name == "Player" and message_label != null:
		message_label.text = zone_message


func _on_body_exited(body: Node2D) -> void:
	if body.name == "Player" and message_label != null:
		message_label.text = ""

extends Area2D

@export var item_type: String = "coin"
@export var amount: int = 1


func _ready() -> void:
	if item_type == "heart":
		modulate = Color(1.0, 0.3, 0.3)
	elif item_type == "key":
		modulate = Color(1.0, 0.9, 0.2)
	body_entered.connect(_on_body_entered)


func _on_body_entered(body: Node2D) -> void:
	if body.name == "Player":
		if body.has_method("collect"):
			body.collect(item_type, amount)
		queue_free()

extends StaticBody2D

signal opened
signal closed

@export var requires_key: bool = false
@export var is_open: bool = false

@onready var collision_shape: CollisionShape2D = $CollisionShape2D
@onready var interaction_area: Area2D = $InteractionArea

var current_player: CharacterBody2D = null
var _frame_count: int = 0
var _last_interact_frame: int = -1


func _ready() -> void:
	interaction_area.body_entered.connect(_on_interaction_body_entered)
	interaction_area.body_exited.connect(_on_interaction_body_exited)
	_update_appearance()


func _process(_delta: float) -> void:
	_frame_count += 1
	if Input.is_action_just_pressed("interact"):
		_try_interact()


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("interact"):
		_try_interact()


func _try_interact() -> void:
	if _last_interact_frame == _frame_count:
		return
	_last_interact_frame = _frame_count

	if is_open:
		return

	var p: CharacterBody2D = _get_interacting_player()
	if p != null:
		if requires_key:
			var player_keys: int = int(p.get("keys"))
			if player_keys > 0:
				p.set("keys", player_keys - 1)
				open()
		else:
			open()


func _get_interacting_player() -> CharacterBody2D:
	if current_player != null:
		return current_player
	for body in interaction_area.get_overlapping_bodies():
		if body.name == "Player" and body is CharacterBody2D:
			return body as CharacterBody2D
	var scene_player: Node = get_tree().current_scene.find_child("Player", true, false)
	if scene_player != null and scene_player is CharacterBody2D:
		var cb := scene_player as CharacterBody2D
		if global_position.distance_to(cb.global_position) < 60.0:
			return cb
	return null


func open() -> void:
	if is_open:
		return
	is_open = true
	collision_shape.set_deferred("disabled", true)
	_update_appearance()
	opened.emit()


func close() -> void:
	if not is_open:
		return
	is_open = false
	collision_shape.set_deferred("disabled", false)
	_update_appearance()
	closed.emit()


func _update_appearance() -> void:
	if is_open:
		modulate.a = 0.3
	else:
		modulate.a = 1.0


func _on_interaction_body_entered(body: Node2D) -> void:
	if body.name == "Player" and body is CharacterBody2D:
		current_player = body as CharacterBody2D


func _on_interaction_body_exited(body: Node2D) -> void:
	if body == current_player:
		current_player = null

